import { describe, it } from "vitest";
import { nextGeneration as orig, type Cell } from "./__orig.js";
import { nextGeneration as next } from "./game-of-life.js";
const s = (c: Cell[]) => [...c].sort(([a,b],[x,y]) => a-x || b-y);
const rnd = (): Cell[] => Array.from({length: 12}, () => [Math.floor(Math.random()*7)-3, Math.floor(Math.random()*7)-3] as Cell);
describe("old vs new", () => {
  it("agree on the overpopulation input", () => {
    const inp: Cell[] = [[0,0],[1,0],[2,0],[1,1],[0,2],[1,2],[2,2]];
    console.log("orig:", JSON.stringify(s(orig(inp))));
    console.log("new :", JSON.stringify(s(next(inp))));
  });
  it("agree on 300 random boards", () => {
    for (let i=0;i<300;i++){
      const inp = rnd();
      const a = JSON.stringify(s(orig(inp)));
      const b = JSON.stringify(s(next(inp)));
      if (a!==b) throw new Error(`MISMATCH on ${JSON.stringify(inp)}\n orig=${a}\n new =${b}`);
    }
    console.log("300 random boards: identical");
  });
});
EOF
